corporate_design.toad_component_blueprint:
canvas {
  size: 900px 560px;
  fill: #F8FAFC;
  font-family: "Inter, sans-serif";
}

>blue = #0369A1;
>red = #DC2626;

rect #hospitalBanner {
  at: center of canvas;
  size: 820px 460px;
  fill: #FFFFFF;
  stroke: #CBD5E1;
  stroke-width: 1px;
  radius: 8px;
}

text #hospTitle {
  at: top left of #hospitalBanner offset 36px 36px;
  content: "ST. LUKAS KLINIKUM // ZENTRALE NOTAUFNAHME";
  font-size: 14px;
  font-weight: 700;
  color: >red;
}

text #hospMain {
  at: below #hospTitle offset 16px;
  content: "24/7 Notfallversorgung & Herzkatheterlabor";
  font-size: 28px;
  font-weight: 700;
  color: >blue;
}
